module float_multi(
    input clk, input rst, 
    input [31:0] a, input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    localparam INIT = 3'd0;
    localparam INPUT = 3'd1;
    localparam SPECIAL_CASES = 3'd2;
    localparam NORMALIZE = 3'd3;
    localparam MULTIPLY = 3'd4;
    localparam ROUND_ADJUST = 3'd5;
    localparam OUTPUT = 3'd6;
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            counter <= 3'd0;
        end else begin
            case(counter)
                INIT: begin
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_sign <= a[31];
                    b_sign <= b[31];
                    counter <= INPUT;
                end

                INPUT: begin
                    if((a_exponent == 8'hFF && a_mantissa != 24'h0) || (b_exponent == 8'hFF && b_mantissa != 24'h0)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        counter <= OUTPUT;
                    end else if(a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        counter <= OUTPUT;
                    end else begin
                        if(a_exponent == 8'h0) begin
                            a_mantissa <= {1'b0, a[22:0]};
                            a_exponent <= 8'h1;
                        end
                        if(b_exponent == 8'h0) begin
                            b_mantissa <= {1'b0, b[22:0]};
                            b_exponent <= 8'h1;
                        end
                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 8'h7F;
                        z_sign <= a_sign ^ b_sign;
                        counter <= MULTIPLY;
                    end
                end

                MULTIPLY: begin
                    guard_bit <= product[24];
                    round_bit <= product[23];
                    sticky <= |product[22:0];

                    if(guard_bit & (round_bit | sticky | product[23])) begin
                        z_mantissa <= product[49:25] + 1;
                        if(z_mantissa[23])
                            z_exponent <= z_exponent + 1;
                    end else begin
                        z_mantissa <= product[49:25];
                    end

                    if(z_exponent >= 8'hFF) begin
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if(z_exponent <= 8'h0) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end

                    counter <= OUTPUT;
                end

                OUTPUT: begin
                    counter <= INIT;
                end
            endcase
        end
    end
endmodule
